import React from 'react';

const COLOR = { Low: '#27ae60', Medium: '#f39c12', High: '#e74c3c' };
const NOTE = {
  Low:    'Your risk level is low. Continue maintaining a healthy lifestyle.',
  Medium: 'Moderate risk detected. Consider scheduling a check-up with your doctor.',
  High:   'High risk detected. Please consult a healthcare professional as soon as possible.',
};

export default function ResultCard({ result }) {
  const { probability, risk_level } = result;
  const color = COLOR[risk_level];

  return (
    <div className="result-card" style={{ borderLeft: `6px solid ${color}` }}>
      <h2>Prediction Result</h2>
      <div className="result-risk" style={{ color }}>{risk_level} Risk</div>
      <div className="result-prob">
        Stroke Probability: <strong>{probability}%</strong>
      </div>
      <p className="result-note">{NOTE[risk_level]}</p>
    </div>
  );
}
